56	
57	const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
58	
59	const JobDetailView = ({
60	  selectedJobId,
61	  selectedJob,
62	  results,
63	  setResults,
64	  existingResumes,
65	  setExistingResumes,
66	  onJobCreated,
67	  onAuthRequired,
68	  onJobUpdated,
69	  isAuthenticated = true,
70	  pastJobs = [],
71	  onBack,
72	}: JobDetailViewProps) => {
73	  const { user, profile, refreshProfile } = useAuth();
74	  const { data: config } = usePlatformConfig();
75	
76	  const [jobTitle, setJobTitle] = useState("");
77	  const [jobDescription, setJobDescription] = useState("");
78	  const [files, setFiles] = useState<UploadedFile[]>([]);
79	  const [selectedFileIndexes, setSelectedFileIndexes] = useState<Set<number>>(new Set());
80	  const [ranking, setRanking] = useState(false);
81	  const [rankingProgress, setRankingProgress] = useState(0);
82	  const [scoredCount, setScoredCount] = useState(0);
83	  const [totalToScore, setTotalToScore] = useState(0);
84	  const [selectedCandidateId, setSelectedCandidateId] = useState<string | null>(null);
85	  const [dragOver, setDragOver] = useState(false);
86	  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
87	  const [validationErrors, setValidationErrors] = useState<string[]>([]);
88	  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
89	  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
90	  const [deleting, setDeleting] = useState(false);
91	  const [analyzingJd, setAnalyzingJd] = useState(false);
92	  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
93	  const [showArchived, setShowArchived] = useState(false);
94	  const [stageFilter, setStageFilter] = useState<HiringStage | null>(null);
95	  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
96	  const [stuckJobDetected, setStuckJobDetected] = useState(false);
97	  const [retrying, setRetrying] = useState(false);
